INSERT INTO notify.kinds (code, channels) VALUES
  ('org_invite', ARRAY['email']),
  ('chat_message', ARRAY['portal', 'email'])
ON CONFLICT (code) DO UPDATE SET channels = EXCLUDED.channels;

DELETE FROM notify.kinds AS k
 WHERE k.code NOT IN ('org_invite', 'chat_message')
   AND NOT EXISTS (SELECT 1 FROM notify.notifications AS n WHERE n.kind = k.code)
   AND NOT EXISTS (SELECT 1 FROM notify.email_outbox AS e WHERE e.template = k.code);
